select * from (
) x order by
x.proj_no desc x.proj_nm desc x.cust_nm desc nulls last x.pm_user_nm desc x.phase_nm desc nulls last x.sop_days desc nulls last x.slip_days desc nulls last x.late_cnt desc nulls last x.ready_pct desc nulls last x.open_issue_cnt desc nulls last x.next_gate_date desc nulls last x.progress_pct desc x.plan_hours desc nulls last x.conf_hours desc x.burn_pct desc nulls last x.remain_hours desc nulls last x.sop_date desc nulls last ,
x.proj_id limit #{page.size} offset #{page.offset}

mapper.sql:
from pms_task k join pms_project p on p.proj_id = k.proj_id
 where k.owner_user_id = #{userId} and k.is_summary = 'N' and k.status in ('NOT_STARTED', 'IN_PROGRESS')
   and p.status in ('DRAFT', 'ACTIVE', 'ON_HOLD') and k.plan_end <= #{until}

from pms_deliverable d join pms_task t on t.task_id = d.task_id join pms_project p on p.proj_id = d.proj_id
 where coalesce(d.owner_user_id, t.owner_user_id) = #{userId} and d.status in ('NONE', 'REJECTED')
   and p.status in ('DRAFT', 'ACTIVE', 'ON_HOLD') and coalesce(d.due_date, t.plan_end) <= #{until}
